WE2 = WE + WP[0]; WP2 = WP - WP[0]
def mats(S):
    Si=np.linalg.inv(S)
    return dict(WE=WE2@S, WP=WP2@S, WU=Si@WU, QK0=Si@QK0@Si.T, QK1=Si@QK1@Si.T, OV0=Si@OV0@S, OV1=Si@OV1@S)
def targets(S):
    T=mats(S)
    return dict(QK0=np.tril(T['QK0'],-1)/np.linalg.norm(QK0), QK1=np.tril(T['QK1'],-1)/np.linalg.norm(QK1),
                OV0=np.tril(T['OV0'],-1)/np.linalg.norm(OV0), OV1=np.tril(T['OV1'],-1)/np.linalg.norm(OV1),
                WU=np.tril(T['WU'][:, :4],-1)/np.linalg.norm(WU), WP=np.tril(T['WP'][1:,:],-1)/np.linalg.norm(WP))
def obj2(p):
    S=expm(p.reshape(4,4)); T=targets(S)
    return sum((v**2).sum() for v in T.values())
